import copy


def _validated(events, source):
    result = []
    previous = -1
    try:
        iterator = iter(events)
    except TypeError:
        raise ValueError(f"{source} must be iterable") from None
    for position, event in enumerate(iterator):
        if not isinstance(event, (tuple, list)) or len(event) != 2:
            raise ValueError("events must be timestamp-payload pairs")
        timestamp, payload = event
        if isinstance(timestamp, bool) or not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError("timestamps must be nonnegative integers")
        if timestamp < previous:
            raise ValueError(f"{source} events are out of order")
        previous = timestamp
        result.append((timestamp, payload, source, position))
    return result


def merge_events(video, audio) -> tuple[tuple[int, object], ...]:
    tagged = _validated(video, "video") + _validated(audio, "audio")
    tagged.sort(key=lambda event: (event[0], 0 if event[2] == "audio" else 1, event[3]))
    return tuple((timestamp, copy.deepcopy(payload)) for timestamp, payload, _, _ in tagged)
```

